17	package com.google.zxing.common;
18	
19	import java.util.List;
20	
21	/**
22	 * <p>Encapsulates the result of decoding a matrix of bits. This typically
23	 * applies to 2D barcode formats. For now it contains the raw bytes obtained,
24	 * as well as a String interpretation of those bytes, if applicable.</p>
25	 *
26	 * @author Sean Owen
27	 */
28	public final class DecoderResult {
29	
30	  private final byte[] rawBytes;
31	  private int numBits;
32	  private final String text;
33	  private final List<byte[]> byteSegments;
34	  private final String ecLevel;
35	  private Integer errorsCorrected;
36	  private Integer erasures;
37	  private Object other;
38	  private Boolean readerInit;
39	  private final int structuredAppendParity;
40	  private final int structuredAppendSequenceNumber;
41	  private final int symbologyModifier;
42	
43	  public DecoderResult(byte[] rawBytes,
44	                       String text,
45	                       List<byte[]> byteSegments,
46	                       String ecLevel) {
47	    this(rawBytes, text, byteSegments, ecLevel, -1, -1, 0);
48	  }
49	
50	  public DecoderResult(byte[] rawBytes,
51	                       String text,
52	                       List<byte[]> byteSegments,
53	                       String ecLevel,
54	                       int symbologyModifier) {
55	    this(rawBytes, text, byteSegments, ecLevel, -1, -1, symbologyModifier);
56	  }
57	
58	  public DecoderResult(byte[] rawBytes,
59	                       String text,
60	                       List<byte[]> byteSegments,
61	                       String ecLevel,
62	                       int saSequence,
63	                       int saParity) {
64	    this(rawBytes, text, byteSegments, ecLevel, saSequence, saParity, 0);
65	  }
66	
67	  public DecoderResult(byte[] rawBytes,
68	                       String text,
69	                       List<byte[]> byteSegments,
70	                       String ecLevel,
71	                       int saSequence,
72	                       int saParity,
73	                       int symbologyModifier) {
74	    this.rawBytes = rawBytes;
75	    this.numBits = rawBytes == null ? 0 : 8 * rawBytes.length;
76	    this.text = text;
77	    this.byteSegments = byteSegments;
78	    this.ecLevel = ecLevel;
79	    this.structuredAppendParity = saParity;
80	    this.structuredAppendSequenceNumber = saSequence;
81	    this.symbologyModifier = symbologyModifier;
82	  }
83	
84	  /**
85	   * @return raw bytes representing the result, or {@code null} if not applicable
86	   */
87	  public byte[] getRawBytes() {
88	    return rawBytes;
89	  }
90	
91	  /**
92	   * @return how many bits of {@link #getRawBytes()} are valid; typically 8 times its length
93	   * @since 3.3.0
94	   */
95	  public int getNumBits() {
96	    return numBits;
97	  }
98	
99	  /**
100	   * @param numBits overrides the number of bits that are valid in {@link #getRawBytes()}
101	   * @since 3.3.0
102	   */
103	  public void setNumBits(int numBits) {
104	    this.numBits = numBits;
105	  }
106	
107	  /**
108	   * @return text representation of the result
109	   */
110	  public String getText() {
111	    return text;
112	  }
113	
114	  /**
115	   * @return list of byte segments in the result, or {@code null} if not applicable
116	   */
117	  public List<byte[]> getByteSegments() {
118	    return byteSegments;
119	  }
120	
121	  /**
122	   * @return name of error correction level used, or {@code null} if not applicable
123	   */
124	  public String getECLevel() {
125	    return ecLevel;
126	  }
127	
128	  /**
129	   * @return number of errors corrected, or {@code null} if not applicable
130	   */
131	  public Integer getErrorsCorrected() {
132	    return errorsCorrected;
133	  }
134	
135	  public void setErrorsCorrected(Integer errorsCorrected) {
136	    this.errorsCorrected = errorsCorrected;
137	  }
138	
139	  /**
140	   * @return number of erasures corrected, or {@code null} if not applicable
141	   */
142	  public Integer getErasures() {
143	    return erasures;
144	  }
145	
146	  public void setErasures(Integer erasures) {
147	    this.erasures = erasures;
148	  }
149	
150	  /**
151	   * @return arbitrary additional metadata
152	   */
153	  public Object getOther() {
154	    return other;
155	  }
156	
157	  public void setOther(Object other) {
158	    this.other = other;
159	  }
160	
161	  /**
162	   * @return whether or not the message is a reader initialization message,
163	   * or {@code null} if not applicable
164	   */
165	  public Boolean getReaderInit() {
166	    return readerInit;
167	  }
168	
169	  public void setReaderInit(Boolean readerInit) {
170	    this.readerInit = readerInit;
171	  }
172	
173	  public boolean hasStructuredAppend() {
174	    return structuredAppendParity >= 0 && structuredAppendSequenceNumber >= 0;
175	  }
176	
177	  public int getStructuredAppendParity() {
178	    return structuredAppendParity;
179	  }
180	
181	  public int getStructuredAppendSequenceNumber() {
182	    return structuredAppendSequenceNumber;
183	  }
184	
185	  public int getSymbologyModifier() {
186	    return symbologyModifier;
187	  }
188	
189	}
