18	
19	import com.google.zxing.BinaryBitmap;
20	import com.google.zxing.DecodeHintType;
21	import com.google.zxing.NotFoundException;
22	import com.google.zxing.Reader;
23	import com.google.zxing.ReaderException;
24	import com.google.zxing.Result;
25	import com.google.zxing.ResultPoint;
26	
27	import java.util.ArrayList;
28	import java.util.List;
29	import java.util.Map;
30	
31	/**
32	 * <p>Attempts to locate multiple barcodes in an image by repeatedly decoding portion of the image.
33	 * After one barcode is found, the areas left, above, right and below the barcode's
34	 * {@link ResultPoint}s are scanned, recursively.</p>
35	 *
36	 * <p>A caller may want to also employ {@link ByQuadrantReader} when attempting to find multiple
37	 * 2D barcodes, like QR Codes, in an image, where the presence of multiple barcodes might prevent
38	 * detecting any one of them.</p>
39	 *
40	 * <p>That is, instead of passing a {@link Reader} a caller might pass
41	 * {@code new ByQuadrantReader(reader)}.</p>
42	 *
43	 * @author Sean Owen
44	 */
45	public final class GenericMultipleBarcodeReader implements MultipleBarcodeReader {
46	
47	  private static final int MIN_DIMENSION_TO_RECUR = 100;
48	  private static final int MAX_DEPTH = 4;
49	
50	  static final Result[] EMPTY_RESULT_ARRAY = new Result[0];
51	
52	  private final Reader delegate;
53	
54	  public GenericMultipleBarcodeReader(Reader delegate) {
55	    this.delegate = delegate;
56	  }
57	
58	  @Override
59	  public Result[] decodeMultiple(BinaryBitmap image) throws NotFoundException {
60	    return decodeMultiple(image, null);
61	  }
62	
63	  @Override
64	  public Result[] decodeMultiple(BinaryBitmap image, Map<DecodeHintType,?> hints)
65	      throws NotFoundException {
66	    List<Result> results = new ArrayList<>();
67	    doDecodeMultiple(image, hints, results, 0, 0, 0);
68	    if (results.isEmpty()) {
69	      throw NotFoundException.getNotFoundInstance();
70	    }
71	    return results.toArray(EMPTY_RESULT_ARRAY);
72	  }
73	
74	  private void doDecodeMultiple(BinaryBitmap image,
75	                                Map<DecodeHintType,?> hints,
76	                                List<Result> results,
77	                                int xOffset,
78	                                int yOffset,
79	                                int currentDepth) {
80	    if (currentDepth > MAX_DEPTH) {
81	      return;
82	    }
83	
84	    Result result;
85	    try {
86	      result = delegate.decode(image, hints);
87	    } catch (ReaderException ignored) {
88	      return;
89	    }
90	    boolean alreadyFound = false;
91	    for (Result existingResult : results) {
92	      if (existingResult.getText().equals(result.getText())) {
93	        alreadyFound = true;
94	        break;
95	      }
96	    }
97	    if (!alreadyFound) {
98	      results.add(translateResultPoints(result, xOffset, yOffset));
99	    }
100	    ResultPoint[] resultPoints = result.getResultPoints();
101	    if (resultPoints == null || resultPoints.length == 0) {
102	      return;
103	    }
104	    int width = image.getWidth();
105	    int height = image.getHeight();
106	    float minX = width;
107	    float minY = height;
108	    float maxX = 0.0f;
109	    float maxY = 0.0f;
110	    for (ResultPoint point : resultPoints) {
111	      if (point == null) {
112	        continue;
113	      }
114	      float x = point.getX();
115	      float y = point.getY();
116	      if (x < minX) {
117	        minX = x;
118	      }
119	      if (y < minY) {
120	        minY = y;
121	      }
122	      if (x > maxX) {
123	        maxX = x;
124	      }
125	      if (y > maxY) {
126	        maxY = y;
127	      }
128	    }
129	
130	    // Decode left of barcode
131	    if (minX > MIN_DIMENSION_TO_RECUR) {
132	      doDecodeMultiple(image.crop(0, 0, (int) minX, height),
133	                       hints, results,
134	                       xOffset, yOffset,
135	                       currentDepth + 1);
136	    }
137	    // Decode above barcode
138	    if (minY > MIN_DIMENSION_TO_RECUR) {
139	      doDecodeMultiple(image.crop(0, 0, width, (int) minY),
140	                       hints, results,
141	                       xOffset, yOffset,
142	                       currentDepth + 1);
143	    }
144	    // Decode right of barcode
145	    if (maxX < width - MIN_DIMENSION_TO_RECUR) {
146	      doDecodeMultiple(image.crop((int) maxX, 0, width - (int) maxX, height),
147	                       hints, results,
148	                       xOffset + (int) maxX, yOffset,
149	                       currentDepth + 1);
150	    }
151	    // Decode below barcode
152	    if (maxY < height - MIN_DIMENSION_TO_RECUR) {
153	      doDecodeMultiple(image.crop(0, (int) maxY, width, height - (int) maxY),
154	                       hints, results,
155	                       xOffset, yOffset + (int) maxY,
156	                       currentDepth + 1);
157	    }
158	  }
159	
160	  private static Result translateResultPoints(Result result, int xOffset, int yOffset) {
161	    ResultPoint[] oldResultPoints = result.getResultPoints();
162	    if (oldResultPoints == null) {
163	      return result;
164	    }
165	    ResultPoint[] newResultPoints = new ResultPoint[oldResultPoints.length];
166	    for (int i = 0; i < oldResultPoints.length; i++) {
167	      ResultPoint oldPoint = oldResultPoints[i];
168	      if (oldPoint != null) {
169	        newResultPoints[i] = new ResultPoint(oldPoint.getX() + xOffset, oldPoint.getY() + yOffset);
170	      }
171	    }
172	    Result newResult = new Result(result.getText(),
173	                                  result.getRawBytes(),
174	                                  result.getNumBits(),
175	                                  newResultPoints,
176	                                  result.getBarcodeFormat(),
177	                                  result.getTimestamp());
178	    newResult.putAllMetadata(result.getResultMetadata());
179	    return newResult;
180	  }
181	
182	}
