29	/**
30	 * Writes a {@link BitMatrix} to {@link BufferedImage},
31	 * file or stream. Provided here instead of core since it depends on
32	 * Java SE libraries.
33	 *
34	 * @author Sean Owen
35	 */
36	public final class MatrixToImageWriter {
37	
38	  private static final MatrixToImageConfig DEFAULT_CONFIG = new MatrixToImageConfig();
39	
40	  private MatrixToImageWriter() {}
41	
42	  /**
43	   * Renders a {@link BitMatrix} as an image, where "false" bits are rendered
44	   * as white, and "true" bits are rendered as black. Uses default configuration.
45	   *
46	   * @param matrix {@link BitMatrix} to write
47	   * @return {@link BufferedImage} representation of the input
48	   */
49	  public static BufferedImage toBufferedImage(BitMatrix matrix) {
50	    return toBufferedImage(matrix, DEFAULT_CONFIG);
51	  }
52	
53	  /**
54	   * As {@link #toBufferedImage(BitMatrix)}, but allows customization of the output.
55	   *
56	   * @param matrix {@link BitMatrix} to write
57	   * @param config output configuration
58	   * @return {@link BufferedImage} representation of the input
59	   */
60	  public static BufferedImage toBufferedImage(BitMatrix matrix, MatrixToImageConfig config) {
61	    int width = matrix.getWidth();
62	    int height = matrix.getHeight();
63	    BufferedImage image = new BufferedImage(width, height, config.getBufferedImageColorModel());
64	    int onColor = config.getPixelOnColor();
65	    int offColor = config.getPixelOffColor();
66	    int[] rowPixels = new int[width];
67	    BitArray row = new BitArray(width);
68	    for (int y = 0; y < height; y++) {
69	      row = matrix.getRow(y, row);
70	      for (int x = 0; x < width; x++) {
71	        rowPixels[x] = row.get(x) ? onColor : offColor;
72	      }
73	      image.setRGB(0, y, width, 1, rowPixels, 0, width);
74	    }
75	    return image;
76	  }
77	
78	  /**
79	   * @param matrix {@link BitMatrix} to write
80	   * @param format image format
81	   * @param file file {@link File} to write image to
82	   * @throws IOException if writes to the file fail
83	   * @deprecated use {@link #writeToPath(BitMatrix, String, Path)}
84	   */
85	  @Deprecated
86	  public static void writeToFile(BitMatrix matrix, String format, File file) throws IOException {
87	    writeToPath(matrix, format, file.toPath());
88	  }
89	
90	  /**
91	   * Writes a {@link BitMatrix} to a file with default configuration.
92	   *
93	   * @param matrix {@link BitMatrix} to write
94	   * @param format image format
95	   * @param file file {@link Path} to write image to
96	   * @throws IOException if writes to the stream fail
97	   * @see #toBufferedImage(BitMatrix)
98	   */
99	  public static void writeToPath(BitMatrix matrix, String format, Path file) throws IOException {
100	    writeToPath(matrix, format, file, DEFAULT_CONFIG);
101	  }
102	
103	  /**
104	   * @param matrix {@link BitMatrix} to write
105	   * @param format image format
106	   * @param file file {@link File} to write image to
107	   * @param config output configuration
108	   * @throws IOException if writes to the file fail
109	   * @deprecated use {@link #writeToPath(BitMatrix, String, Path, MatrixToImageConfig)}
110	   */
111	  @Deprecated
112	  public static void writeToFile(BitMatrix matrix, String format, File file, MatrixToImageConfig config) 
113	      throws IOException {
114	    writeToPath(matrix, format, file.toPath(), config);
115	  }
116	
117	  /**
118	   * As {@link #writeToPath(BitMatrix, String, Path)}, but allows customization of the output.
119	   *
120	   * @param matrix {@link BitMatrix} to write
121	   * @param format image format
122	   * @param file file {@link Path} to write image to
123	   * @param config output configuration
124	   * @throws IOException if writes to the file fail
125	   */
126	  public static void writeToPath(BitMatrix matrix, String format, Path file, MatrixToImageConfig config)
127	      throws IOException {
128	    BufferedImage image = toBufferedImage(matrix, config);
129	    if (!ImageIO.write(image, format, file.toFile())) {
130	      throw new IOException("Could not write an image of format " + format + " to " + file);
131	    }
132	  }
133	
134	  /**
135	   * Writes a {@link BitMatrix} to a stream with default configuration.
136	   *
137	   * @param matrix {@link BitMatrix} to write
138	   * @param format image format
139	   * @param stream {@link OutputStream} to write image to
140	   * @throws IOException if writes to the stream fail
141	   * @see #toBufferedImage(BitMatrix)
142	   */
143	  public static void writeToStream(BitMatrix matrix, String format, OutputStream stream) throws IOException {
144	    writeToStream(matrix, format, stream, DEFAULT_CONFIG);
145	  }
146	
147	  /**
148	   * As {@link #writeToStream(BitMatrix, String, OutputStream)}, but allows customization of the output.
149	   *
150	   * @param matrix {@link BitMatrix} to write
151	   * @param format image format
152	   * @param stream {@link OutputStream} to write image to
153	   * @param config output configuration
154	   * @throws IOException if writes to the stream fail
155	   */
156	  public static void writeToStream(BitMatrix matrix, String format, OutputStream stream, MatrixToImageConfig config) 
157	      throws IOException {  
158	    BufferedImage image = toBufferedImage(matrix, config);
159	    if (!ImageIO.write(image, format, stream)) {
160	      throw new IOException("Could not write an image of format " + format);
161	    }
162	  }
163	
164	}
