32	import java.util.concurrent.ExecutorService;
33	import java.util.concurrent.Executors;
34	import java.util.concurrent.Future;
35	
36	/**
37	 * This simple command line utility decodes files, directories of files, or URIs which are passed
38	 * as arguments. By default it uses the normal decoding algorithms, but you can pass --try_harder
39	 * to request that hint. The raw text of each barcode is printed, and when running against
40	 * directories, summary statistics are also displayed.
41	 *
42	 * @author dswitkin@google.com (Daniel Switkin)
43	 * @author Sean Owen
44	 */
45	public final class CommandLineRunner {
46	
47	  private CommandLineRunner() {
48	  }
49	
50	  public static void main(String[] args) throws Exception {
51	    DecoderConfig config = new DecoderConfig();
52	    JCommander jCommander = new JCommander(config);
53	    jCommander.parse(args);
54	    jCommander.setProgramName(CommandLineRunner.class.getSimpleName());
55	    if (config.help) {
56	      jCommander.usage();
57	      return;
58	    }
59	
60	    List<URI> inputs = new ArrayList<>(config.inputPaths.size());
61	    for (String inputPath : config.inputPaths) {
62	      URI uri;
63	      try {
64	        uri = new URI(inputPath);
65	      } catch (URISyntaxException use) {
66	        // Assume it must be a file
67	        if (!Files.exists(Paths.get(inputPath))) {
68	          throw use;
69	        }
70	        uri = new URI("file", inputPath, null);
71	      }
72	      inputs.add(uri);
73	    }
74	
75	    do {
76	      inputs = retainValid(expand(inputs), config.recursive);
77	    } while (config.recursive && isExpandable(inputs));
78	
79	    int numInputs = inputs.size();
80	    if (numInputs == 0) {
81	      jCommander.usage();
82	      return;
83	    }
84	
85	    Queue<URI> syncInputs = new ConcurrentLinkedQueue<>(inputs);
86	    int numThreads = Math.min(numInputs, Runtime.getRuntime().availableProcessors());
87	    int successful = 0;    
88	    if (numThreads > 1) {
89	      ExecutorService executor = Executors.newFixedThreadPool(numThreads);
90	      Collection<Future<Integer>> futures = new ArrayList<>(numThreads);
91	      for (int x = 0; x < numThreads; x++) {
92	        futures.add(executor.submit(new DecodeWorker(config, syncInputs)));
93	      }
94	      executor.shutdown();
95	      for (Future<Integer> future : futures) {
96	        successful += future.get();
97	      }
98	    } else {
99	      successful += new DecodeWorker(config, syncInputs).call();
100	    }
101	
102	    if (!config.brief && numInputs > 1) {
103	      System.out.println("\nDecoded " + successful + " files out of " + numInputs +
104	          " successfully (" + (successful * 100 / numInputs) + "%)\n");
105	    }
106	  }
107	
108	  private static List<URI> expand(Iterable<URI> inputs) throws IOException {
109	    List<URI> expanded = new ArrayList<>();
110	    for (URI input : inputs) {
111	      if (isFileOrDir(input)) {
112	        Path inputPath = Paths.get(input);
113	        if (Files.isDirectory(inputPath)) {
114	          try (DirectoryStream<Path> childPaths = Files.newDirectoryStream(inputPath)) {
115	            for (Path childPath : childPaths) {
116	              expanded.add(childPath.toUri());
117	            }
118	          }
119	        } else {
120	          expanded.add(input);
121	        }
122	      } else {
123	        expanded.add(input);
124	      }
125	    }
126	    for (int i = 0; i < expanded.size(); i++) {
127	      URI input = expanded.get(i);
128	      if (input.getScheme() == null) {
129	        expanded.set(i, Paths.get(input.getRawPath()).toUri());
130	      }
131	    }
132	    return expanded;
133	  }
134	
135	  private static List<URI> retainValid(Iterable<URI> inputs, boolean recursive) {
136	    List<URI> retained = new ArrayList<>();
137	    for (URI input : inputs) {
138	      boolean retain;
139	      if (isFileOrDir(input)) {
140	        Path inputPath = Paths.get(input);
141	        retain =
142	            !inputPath.getFileName().toString().startsWith(".") &&
143	            (recursive || !Files.isDirectory(inputPath));
144	      } else {
145	        retain = true;
146	      }
147	      if (retain) {
148	        retained.add(input);
149	      }
150	    }
151	    return retained;
152	  }
153	
154	  private static boolean isExpandable(Iterable<URI> inputs) {
155	    for (URI input : inputs) {
156	      if (isFileOrDir(input) && Files.isDirectory(Paths.get(input))) {
157	        return true;
158	      }
159	    }
160	    return false;
161	  }
162	
163	  private static boolean isFileOrDir(URI uri) {
164	    return "file".equals(uri.getScheme());
165	  }
166	
167	}
